{
  "journeyId": "{{ij_mg_journey_id}}",
  "order": 1,
  "name": "MG behaviour tick only",
  "description": "BehaviourMetricTick-only: acceptanceRate>=1 AND cancellationRate<=50 (no ride vars)",
  "conditionType": "AcceptanceRate",
  "conditionOperator": "GTE",
  "conditionValue": 1,
  "rewardType": "Coins",
  "rewardValue": 15,
  "evaluation": {
    "logic": {
      "and": [
        {
          ">=": [
            {
              "var": "acceptanceRate"
            },
            1
          ]
        },
        {
          "<=": [
            {
              "var": "cancellationRate"
            },
            50
          ]
        }
      ]
    }
  }
}

{
  "journeyId": "{{ij_mg_journey_id}}",
  "order": 2,
  "name": "MG JsonLogic ride+behaviour",
  "description": "Ride-end bag: ridesCompleted>=1 AND earnings>=1 AND acceptanceRate>=1 AND cancellationRate<=50",
  "conditionType": "RideCompleted",
  "conditionOperator": "GTE",
  "conditionValue": 1,
  "rewardType": "Coins",
  "rewardValue": 25,
  "evaluation": {
    "logic": {
      "and": [
        {
          ">=": [
            {
              "var": "ridesCompleted"
            },
            1
          ]
        },
        {
          ">=": [
            {
              "var": "earnings"
            },
            1
          ]
        },
        {
          ">=": [
            {
              "var": "acceptanceRate"
            },
            1
          ]
        },
        {
          "<=": [
            {
              "var": "cancellationRate"
            },
            50
          ]
        }
      ]
    }
  }
}

{
  "journeyId": "{{ij_mg_journey_id}}",
  "order": 3,
  "name": "MG exit gate",
  "description": "Exit gate legacy: evaluation.logic false is no-op (no disqualify)",
  "conditionType": "RideCompleted",
  "conditionOperator": "GTE",
  "conditionValue": 0,
  "rewardType": "NoReward",
  "rewardValue": null,
  "evaluation": {
    "logic": {
      "<": [
        {
          "var": "ridesCompleted"
        },
        1
      ]
    }
  }
}

{
  "cohortId": "{{ij_mg_cohort_id}}",
  "journeyId": "{{ij_mg_journey_id}}",
  "startDate": "{{_test_start_date}}",
  "streakRange": 2,
  "enabled": true,
  "maxWaiveOffCount": 0,
  "streakEndRewardType": "NoReward",
  "streakEndRewardValue": null,
  "streakEndRewardExpirationAt": null,
  "streakEndSubscriptionWaiveOff": null,
  "campaignUserLinkType": "OptIn",
  "controlFeatures": [
    {
      "feature": "CanDxCancelBooking",
      "config": false,
      "enableIn": "AllDay"
    },
    {
      "feature": "AutoAssign",
      "config": {
        "defaultOn": true,
        "allowDriverToToggle": false,
        "disableDriverAreaAndDistancePreference": true
      },
      "enableIn": "AllDay"
    },
    {
      "feature": "PoolingPriority",
      "config": {
        "Default": "HIGH"
      },
      "enableIn": "AllDay"
    }
  ],
  "periodDays": 1
}
